import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null) return;

        int N = Integer.parseInt(first.trim());

        Set<Long> full = new HashSet<>();
        List<Set<Long>> pref = new ArrayList<>();
        List<Set<Long>> suff = new ArrayList<>();

        for (int i = 0; i < 10; i++) {
            pref.add(new HashSet<>());
            suff.add(new HashSet<>());
        }

        String ans = null;

        for (int k = 0; k < N; k++) {
            String s = br.readLine().trim();

            if (ans != null) continue;

            long fullCode = encode(s, 0, 10);
            boolean invalid = full.contains(fullCode);

            if (!invalid) {
                for (int j = 1; j <= 9; j++) {
                    long p = encode(s, 0, j);
                    long q = encode(s, j, 10);

                    if (suff.get(j).contains(p) && pref.get(10 - j).contains(q)) {
                        invalid = true;
                        break;
                    }
                }
            }

            if (invalid) {
                ans = s;
            } else {
                full.add(fullCode);
                for (int j = 1; j <= 9; j++) {
                    pref.get(j).add(encode(s, 0, j));
                    suff.get(j).add(encode(s, 10 - j, 10));
                }
            }
        }

        System.out.println(ans == null ? "ok" : ans);
    }

    private static long encode(String s, int l, int r) {
        long h = 0;
        for (int i = l; i < r; i++) {
            h = (h << 5) | (s.charAt(i) - 'a');
        }
        return h;
    }
}
